/* Structured travel information. Mutation and playback remain in app.js. */
(function(root){
'use strict';
function create(h){
  const {ui,D,C,P,esc,icon,btn,textBtn,badge,pageHero,footer,notice,timing,templatePlan,trip,activeTrip,modeName,startName,map,timeline,summary,downloadRow,templateDownloadState,player,transcript,currentStopLink,brandRow,drawerGrip,selectedMapCard,sources,go,render,openAI}=h;
  const content=()=>root.GN_CONTENT||{places:{},tours:{},collections:[],city:{}};
  const db=()=>h.getDB();
  const placeContent=id=>content().places[id]||{};
  const fmt=n=>Number.isFinite(n)?Math.round(n):'—';
  const section=(title,sub='',action='')=>`<div class="rich-section-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>`;
  const list=items=>`<ul class="rich-list">${(items||[]).map(x=>`<li>${esc(typeof x==='string'?x:x.text||x.title)}</li>`).join('')}</ul>`;
  const facts=items=>`<dl class="fact-list">${items.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl>`;
  function weatherSymbol(kind){const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',rain:'M7 17h11a4 4 0 0 0 0-8 6 6 0 0 0-11-2 5 5 0 0 0 0 10M8 20l-1 2m6-2-1 2m6-2-1 2',cloud:'M6 18h12a4 4 0 0 0 0-8 6 6 0 0 0-11-2 5 5 0 0 0-1 10',snow:'M12 3v18M4 7l16 10M4 17 20 7M8 5l4 3 4-3M8 19l4-3 4 3',storm:'M7 17H6A5 5 0 0 1 6 7a6 6 0 0 1 11 2 4 4 0 0 1 1 8h-2M12 13l-3 6h4l-2 4'};const key=/rain|drizzle|shower/i.test(kind||'')?'rain':/thunder|storm/i.test(kind||'')?'storm':/snow/i.test(kind||'')?'snow':/clear|sun/i.test(kind||'')?'sun':'cloud';return `<svg class="weather-symbol" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[key]}"/></svg>`}
  function weatherState(){return h.getWeather?.()||{status:'unsupported',data:null,loading:false}}
  function weatherTime(value){return value?root.GN_WEATHER.formatTime(value):'—'}
  function weatherBrief(){
    const w=weatherState(),d=w.data;
    const now=new Date();
    const vnHour=(now.getUTCHours()+7)%24;
    const vnDay=(now.getUTCDay()+(now.getUTCHours()+7>=24?1:0))%7;
    let kicker='TODAY IN DA NANG',advice='Explore the river, the coast and city stories.';
    if(vnHour>=5&&vnHour<11){
      kicker='MORNING BREEZE · 06:00 – 11:00';
      advice='Fresh air on Son Tra Peninsula or sunrise at My Khe Beach.';
    }else if(vnHour>=11&&vnHour<15){
      kicker='MIDDAY SUN · 11:00 – 15:00';
      advice='Peak sun outside. Cham Museum galleries or a covered cafe pause.';
    }else if(vnHour>=15&&vnHour<18){
      kicker='GOLDEN HOUR · 15:00 – 18:00';
      advice='Soft light & sea breeze. Sunset around 17:18 at My Khe.';
    }else{
      kicker='EVENING RIVER WALK · 18:00 – 23:00';
      advice='Cool riverside breeze. Night market walks and illuminated bridges.';
    }
    const isWeekend=vnDay===0||vnDay===6;
    const weekendBadge=isWeekend?`<span class="weekend-highlight-pill">🐉 Dragon Bridge Fire Show · 21:00 tonight</span>`:'';

    if(!d)return `<div class="city-weather-brief" aria-label="Da Nang weather"><span class="city-weather-copy">${weatherSymbol('cloud')}<span>${w.loading?'Checking Da Nang weather…':'Da Nang weather unavailable'}</span></span>${textBtn(w.loading?'Details':'Check','weather-open',{},'chevron')}</div>`;
    const rain=d.hourly[0]?.precipProbability;
    return `<section class="city-weather-context">
      <button class="city-weather-brief" data-action="weather-open" aria-label="View Da Nang weather details">
        <span class="city-weather-copy">${weatherSymbol(d.current.condition.icon)}<span><strong>${fmt(d.current.temperature)}°</strong> ${esc(d.current.condition.label)}<small>${rain===null||rain===undefined?'Hourly rain unavailable':`Rain this hour ${fmt(rain)}%`}</small></span></span>
        ${icon('chevron')}
      </button>
      <div class="weather-sun-arc-strip">
        <span class="sun-arc-indicator"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#f6a623" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2m0 18v2M4.22 4.22l1.42 1.42m12.72 12.72l1.42 1.42M1 12h2m18 0h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>Golden hour 17:18 · UV: Moderate</span>
        ${weekendBadge}
      </div>
      <div class="local-rhythm-banner">
        <span class="rhythm-tag">${kicker}</span>
        <p>${advice}</p>
      </div>
      <p>${w.stale?'Saved forecast':'City forecast'} · valid ${weatherTime(d.forecastAt)} · Open-Meteo</p>
      ${rain>=50?`<div class="rain-context"><span>Rain is possible. Prefer an indoor visit?</span>${textBtn('See the museum','place',{id:'museum'})}</div>`:''}
    </section>`;
  }
  function weatherCard(){const w=weatherState(),d=w.data;if(!d)return `<section class="weather-card weather-empty" aria-label="Da Nang weather"><div class="row">${weatherSymbol('sun')}<div class="grow"><p class="eyebrow">TODAY IN DA NANG</p><h3>${w.loading?'Checking the forecast…':'A little context for your day'}</h3><p>${w.loading?'Weather data by Open-Meteo':'Weather is unavailable. Your places and plans still work.'}</p></div></div>${textBtn(w.loading?'Weather details':'View weather & retry','weather-open',{},'chevron')}</section>`;const day=d.daily[0],rain=d.hourly[0]?.precipProbability;return `<button class="weather-card" data-action="weather-open" aria-label="View Da Nang weather details"><span class="weather-topline"><span>DA NANG · ${w.stale?'SAVED FORECAST':'WEATHER MODEL'}</span><span>${weatherTime(d.current.time||d.forecastAt)}</span></span><span class="weather-main"><span><strong>${fmt(d.current.temperature)}<sup>°</sup></strong><span>${esc(d.current.condition.label)}</span></span>${weatherSymbol(d.current.condition.kind||d.current.condition.label)}</span><span class="weather-facts"><span>Feels ${fmt(d.current.apparentTemperature)}°</span><span>H ${fmt(day?.max)}° · L ${fmt(day?.min)}°</span><span>${rain===null||rain===undefined?'Rain —':`${fmt(rain)}% rain`}</span></span><span class="weather-caption">${w.stale?'Saved · ':''}Fetched ${weatherTime(d.fetchedAt)} · Open-Meteo${icon('chevron')}</span></button>`}
  function weatherView(){const w=weatherState(),d=w.data;return {title:'Da Nang weather',body:`<div class="page rich-page">${pageHero('A little foresight.','A city forecast to help you prepare.')}${weatherCard()}${w.error?notice(w.error.message,'warning'):''}${d?`${section('The next few hours','Local time · chance of precipitation')}<div class="hourly-weather">${d.hourly.map(x=>`<div><span>${weatherTime(x.time)}</span>${weatherSymbol(x.condition.kind||x.condition.label)}<strong>${fmt(x.temperature)}°</strong><small>${x.precipProbability===null?'—':fmt(x.precipProbability)+'%'} rain</small></div>`).join('')||'<p>Hourly details are not available for this response.</p>'}</div>${section('Looking ahead','Daily forecast estimates')}<div class="forecast-days">${d.daily.map(x=>`<div><span>${esc(root.GN_WEATHER.formatDate(x.date))}</span>${weatherSymbol(x.condition.kind||x.condition.label)}<strong>${fmt(x.max)}° <small>${fmt(x.min)}°</small></strong><small>${x.precipProbability===null?'Rain —':fmt(x.precipProbability)+'% rain'}</small></div>`).join('')}</div><section class="rich-card">${section('Daylight & conditions')}${facts([['Sunrise',weatherTime(d.daily[0]?.sunrise)],['Sunset',weatherTime(d.daily[0]?.sunset)],['Wind',d.current.windKph===null?'Unavailable':fmt(d.current.windKph)+' km/h'],['Forecast valid at',weatherTime(d.forecastAt)],['Fetched at',weatherTime(d.fetchedAt)]])}<p class="fine-print">Fixed city forecast for Da Nang, Vietnam. Model estimates can differ from conditions at a specific place. A beach visit still needs local sea-condition checks.</p></section>`:''}${btn(w.loading?'Checking forecast…':'Refresh forecast','weather-refresh',{},'secondary','refresh')}<p class="fine-print"><a href="https://open-meteo.com/" target="_blank" rel="noopener">Weather data by Open-Meteo</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. No location permission needed. ${w.stale?'These values are saved, not a current fetch.':''}</p></div>`}}
  function placeCard(p){const c=placeContent(p.id);return `<button class="discovery-card rich-place-card" data-action="place" data-id="${p.id}"><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"><span class="body"><span class="card-kicker">${esc(p.category)}</span><strong>${esc(p.name)}</strong><small>${esc(c.shortHook||p.description)}</small><span class="meta">${icon('clock')}${C.formatDuration(p.duration)} visit <span>·</span> ${c.setting==='indoor'?'Indoors':c.setting==='outdoor'?'Outdoors':'Explore & listen'}</span></span></button>`}
  function collectionCard(c){const first=P[c.placeIds[0]];return `<button class="collection-card" data-action="collection-open" data-id="${esc(c.id)}"><img src="${esc(first.image)}" alt="" loading="lazy"><span><small>${c.placeIds.length} places · editorial collection</small><strong>${esc(c.title)}</strong><span>${esc(c.subtitle)}</span></span>${icon('arrow')}</button>`}
  function nextAction(){const t=activeTrip();if(t){const stop=P[t.plan.stops[t.progress.index].id],count=t.progress.visited.length;return `<section class="day-plan-card"><div class="row between"><span class="eyebrow">${t.status==='paused'?'YOUR PAUSED JOURNEY':'YOUR DAY IS UNDER WAY'}</span>${badge(`${count}/${t.plan.stops.length} arrived`,'blue')}</div><h2>${esc(stop.name)}</h2><p>Stop ${t.progress.index+1} of ${t.plan.stops.length} · ${modeName(t.plan.mode)}</p><div class="rich-progress"><span style="width:${count/t.plan.stops.length*100}%"></span></div>${btn(t.status==='paused'?'Resume my trip':'Continue my trip','open-trip',{id:t.id},'','arrow')}</section>`}return `<section class="day-plan-card"><p class="eyebrow">YOUR TIME · YOUR PACE</p><h2>Plan a little discovery.</h2><p>Choose your time. We’ll suggest the stops.</p><div class="time-chips" aria-label="Plan my day">${[120,240,360].map(v=>`<button data-action="quick-plan" data-value="${v}">${v/60} hours${icon('arrow')}</button>`).join('')}</div></section>`}
  function homeView(){return {title:'GoNarra',noheader:true,nav:true,body:`<div class="home-map-screen rich-home" data-snap="${ui.homeSnap}"><div class="map-surface">${root.GN_VISUALS.mapScene(null,{selectedId:ui.selectedMapPlace})}</div><div class="home-top">${brandRow()}<div class="home-city-row"><span class="city-chip">${icon('pin')}Da Nang, Vietnam</span><span class="demo-chip">Illustrated map</span></div><button class="search-box home-search" data-action="home-search">${icon('search')}<span>Places, stories and little discoveries</span>${icon('arrow')}</button><div class="home-quick-filter-row" aria-label="Quick category filters"><button class="quick-filter-pill" data-action="quick-filter" data-value="beach">🌊 My Khe Beach</button><button class="quick-filter-pill" data-action="quick-filter" data-value="culture">🏛 Culture & Art</button><button class="quick-filter-pill" data-action="quick-filter" data-value="nature">🌄 Nature & Views</button><button class="quick-filter-pill" data-action="quick-filter" data-value="all">🍜 Da Nang Food</button></div></div><div class="home-map-tools"><button class="icon-btn map-control" data-action="map-overview" aria-label="Show map overview">${icon('compass')}</button></div><section class="home-drawer" data-snap="${ui.homeSnap}" aria-label="Discover Da Nang">${drawerGrip()}<div class="drawer-content rich-home-feed">${ui.homeSnap==='compact'?`${nextAction()}${textBtn('Explore the whole day','home-expand',{},'up')}`:`<div class="home-day-heading"><div><p class="eyebrow">YOUR CITY COMPANION</p><h1>Your Da Nang day.</h1></div><span>${new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ho_Chi_Minh',day:'numeric',month:'short'}).format(new Date())}</span></div>${weatherBrief()}${nextAction()}${ui.selectedMapPlace?selectedMapCard(ui.selectedMapPlace):''}<section>${section('A story worth a stop','See the place. Hear what makes it special.',textBtn('See all','all-places'))}<div class="discover-grid">${[P.cathedral,P.beach].map(placeCard).join('')}</div></section><section>${section('Find your kind of Da Nang','A few ways to follow your curiosity.')}<div class="collection-list">${content().collections.slice(0,2).map(collectionCard).join('')}</div></section><section>${section('A day, already imagined','Start with a prepared itinerary.',textBtn('All tours','explore-tours'))}<div class="home-tour-strip">${D.templates.map(compactTourCard).join('')}</div></section><section class="rich-card home-essentials">${section('Before you head out','Stories, downloads and visit preparation.')}${textBtn('Open your trip essentials','essentials-open',{},'chevron')}</section>`}</div></section></div>`}}
  function tourCard(t){const plan=templatePlan(t.id),s=timing(plan),c=content().tours[t.id]||{};return `<article class="tour-card-wrapper"><button class="tour-card" data-action="tour" data-id="${t.id}"><img class="cover" src="${t.image}" alt="${esc(t.title)}" loading="lazy"><span class="body"><span class="card-kicker">PREPARED DAY · ENGLISH STORIES</span><h2>${esc(t.title)}</h2><span class="muted small">${esc(t.subtitle)}</span><span class="tour-card-facts"><span>${icon('clock')}${C.formatDuration(s.totalMinutes)}</span><span>${icon('pin')}${plan.stops.length} stops</span><span>${icon('headphones')}${plan.stops.filter(x=>P[x.id].story.audio).length} stories</span></span><span class="card-note">${esc((c.suitedFor||[]).slice(0,2).join(' · ')||'A personal pace · Room to edit')}</span></span></button>${downloadRow(templateDownloadState(t.id),t.id)}</article>`}
  function exploreView(){const tab=ui.exploreTab||'places',q=normalize(ui.search),collection=content().collections.find(x=>x.id===ui.collectionId);let places=Object.values(P).filter(p=>!p.isBreak&&normalize(`${p.name} ${p.localName} ${p.tags.join(' ')}`).includes(q)&&(!collection||collection.placeIds.includes(p.id))&&(ui.filter==='all'||p.tags.includes(ui.filter)));if(ui.exploreSort==='short')places.sort((a,b)=>a.duration-b.duration);else if(ui.exploreSort==='long')places.sort((a,b)=>b.duration-a.duration);const tours=D.templates.filter(t=>normalize(t.title+' '+t.subtitle).includes(q));return {title:'Explore',noheader:true,nav:true,body:`<div class="page rich-page">${pageHero('Follow a little curiosity.','City stories, coastal pauses and routes to make your own.')}${h.searchForm(ui.search)}<div class="segmented" role="tablist" aria-label="Explore collection">${['places','tours'].map(v=>`<button role="tab" aria-selected="${v===tab}" class="${v===tab?'active':''}" data-action="explore-tab" data-value="${v}">${v==='places'?'Places & stories':'Ready-made tours'}</button>`).join('')}</div>${tab==='places'?`<div class="chip-set" aria-label="Place category">${['all','culture','nature','beach'].map(v=>`<button class="chip ${ui.filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${ui.filter===v}">${v==='all'?'All places':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>${collection?`<div class="collection-context"><span>${esc(collection.title)}</span>${textBtn('Clear collection','collection-clear')}</div>`:''}<div class="results-toolbar"><p role="status">${places.length} ${places.length===1?'place':'places'}${ui.search?` for “${esc(ui.search)}”`:''}</p><label>Sort<select id="explore-sort" aria-label="Sort places"><option value="curated" ${!ui.exploreSort||ui.exploreSort==='curated'?'selected':''}>Curated order</option><option value="short" ${ui.exploreSort==='short'?'selected':''}>Shorter visits</option><option value="long" ${ui.exploreSort==='long'?'selected':''}>Longer visits</option></select></label></div>${places.length?`<div class="discover-grid">${places.map(placeCard).join('')}</div>`:`<div class="rich-card empty"><h2>No matches this time.</h2><p>Try a place name, another category or clear the filters.</p>${btn('Show all places','explore-clear',{},'secondary')}</div>`}${section('Another way to explore','Collections from the same place library.')}<div class="collection-list">${content().collections.map(collectionCard).join('')}</div>`:`${section('A prepared day, a personal pace','Compare stops, stories and time. Edit any tour before starting.')}<div class="rich-tour-list">${tours.length?tours.map(tourCard).join(''):notice('No tours match this search. Try another name.')}</div><div class="rich-card">${section('How a prepared tour works')}<ol class="rich-steps"><li><strong>Preview the whole day</strong><p>Check each stop, visit length and estimated transfer.</p></li><li><strong>Make room for you</strong><p>Customize stops or ask for an adjustment before you start.</p></li><li><strong>Listen along the way</strong><p>Download stories ahead of time if signal may be limited.</p></li></ol></div>`}</div>`}}
  function normalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d')}
  function compactTourCard(t){const p=templatePlan(t.id);return `<article class="compact-tour"><button data-action="tour" data-id="${t.id}"><img src="${t.image}" alt="${esc(t.title)}" loading="lazy"><span><strong>${esc(t.title)}</strong><small>${p.stops.length} stops · ${C.formatDuration(timing(p).totalMinutes)}</small></span></button>${downloadRow(templateDownloadState(t.id),t.id)}</article>`}
  function detailBody(p,atStop=false){const c=placeContent(p.id),story=ui.detailTab==='story',t=atStop?trip():null;const bestTimes={cathedral:'08:00 – 10:30 · Morning light',museum:'11:30 – 14:30 · Ideal midday indoor',lunch:'12:00 – 13:30 · Bustling local dining',beach:'15:30 – 17:45 · Golden hour & sunset',mountain:'07:00 – 09:30 · Cool morning ascent',bridge:'18:00 – 21:30 · Night lights & breeze'};return `<article class="place-detail-screen rich-detail"><div class="detail-hero"><img src="${p.image}" alt="${esc(p.name)}"><div class="detail-hero-controls"><button class="icon-btn" data-action="back" aria-label="Back">${icon('back')}</button><button class="icon-btn ${db().favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="Save favorite" aria-pressed="${db().favorites.includes(p.id)}">${icon('bookmark')}</button></div></div><div class="detail-title"><p class="eyebrow">${atStop?`STOP ${t.progress.index+1} OF ${t.plan.stops.length} · ARRIVAL CONFIRMED`:esc(p.category)}</p><h1 tabindex="-1">${esc(p.name)}</h1><p>${esc(p.localName)}</p></div><div class="detail-facts"><span>${icon('clock')}${C.formatDuration(p.duration)} visit</span><span>${icon(c.setting==='indoor'?'home':'compass')}${c.setting==='indoor'?'Indoors':c.setting==='outdoor'?'Outdoors':'Indoor & outdoor'}</span>${bestTimes[p.id]?`<span class="best-time-fact">${icon('clock')}${bestTimes[p.id]}</span>`:''}${p.isBreak?'':`<span>${icon('headphones')}English preview</span>`}</div>${p.isBreak?'':`<div class="detail-tabs" role="tablist" aria-label="Place information">${['about','story'].map(v=>`<button role="tab" aria-selected="${ui.detailTab===v}" class="${ui.detailTab===v?'active':''}" data-action="detail-tab" data-value="${v}">${v==='about'?'About':'Story'}</button>`).join('')}</div>`}<div class="detail-copy">${story&&!p.isBreak?`${player(p)}${section('Listen for these details','A few things to notice as the story unfolds.')}${list(c.audioTakeaways)}<details class="rich-disclosure" ${ui.showTranscript?'open':''}><summary>Read the complete transcript</summary>${transcript(p)}</details><section class="rich-card"><h3>Your story, your pace</h3><p>Pause, change playback speed or read instead. Listening never marks a stop as visited or changes your route.</p></section>`:`<p class="detail-lead">${esc(c.shortHook||p.description)}</p><p>${esc(p.description)}</p>${p.isBreak?'':btn('Listen to this story','listen-detail',{id:p.id},'','headphones')}${section('What makes this stop special')}<div class="highlight-list">${(c.highlights||[]).slice(0,2).map((x,i)=>`<div><span class="highlight-index">0${i+1}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div></div>`).join('')}</div><details class="rich-disclosure"><summary>A suggested way to spend your visit</summary><ol class="rich-steps">${(c.visitRhythm||[]).map(x=>`<li><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p></li>`).join('')}</ol>${list(c.visitTips)}</details><section class="rich-card">${section('Plan your visit')}${facts([['Suggested visit',C.formatDuration(p.duration)],...(c.practicalFacts||[]).filter(x=>!/^Suggested stop$/i.test(x.label)).map(x=>[x.label,x.value])])}</section><details class="rich-disclosure"><summary>Access, etiquette & things to check</summary>${list([...(c.mobility||[]),...(c.etiquette||[])])}<p class="fine-print">Current opening hours, admission fees and entrance details are not verified in this prototype. Check the venue before travelling.</p></details><details class="rich-disclosure"><summary>Location & editorial sources</summary><p>${esc(p.coordinateStatus||'Select a suitable venue near the previous stop.')}</p>${p.coordinates?facts([['Approximate point',`${p.coordinates.lat.toFixed(4)}, ${p.coordinates.lng.toFixed(4)}`]]):''}${sources(p)}</details>`}${p.isBreak?'':`<button class="detail-ask-link" data-action="ask-place" data-id="${p.id}">${icon('chat')}Curious about this place? Ask AI${icon('arrow')}</button>`}${atStop?textBtn('Stay longer · +15 min','extend-stop',{},'clock'):''}${currentStopLink(p.id)}</div>${!atStop&&!p.isBreak?`<div class="detail-floating-bar">${btn('Listen','listen-detail',{id:p.id},'detail-floating-listen','headphones')}${btn('+ Add to plan','add-place-target',{id:p.id},'detail-floating-add secondary')}</div>`:''}</article>`}
  function tourView(){const t=D.templates.find(x=>x.id===ui.templateId)||D.templates[0],p=templatePlan(t.id),c=content().tours[t.id]||{};return {title:'Ready-made tour',body:`<img class="cover-bleed" src="${t.image}" alt="${esc(t.title)}"><div class="page rich-page">${badge('Prepared route · make it your own','blue')}${pageHero(t.title,t.subtitle)}<p class="rich-lead">${esc(t.description)}</p>${summary(p)}<div class="rich-card">${section('This day is for you if…')}${list(c.suitedFor)}</div>${section('The shape of your day','Scheduled times and transfers use demo estimates.',textBtn('Customize','adapt',{id:t.id},'edit'))}${timeline(p,null,true)}<details class="rich-disclosure"><summary>View the route overview</summary>${map(p)}</details><section class="rich-card">${section('Good to know before you go')}${facts([['Start',startName(p.startId)],['Departure',C.formatTime(p.startMinutes)],['Travel',modeName(p.mode)],['Finish',P[p.stops.at(-1).id].name],['Audio','English synthetic previews']])}${list([c.startNote,c.endNote,c.planningNote].filter(Boolean))}</section><div class="two rich-inclusions"><section class="rich-card"><h3>In your tour</h3>${list(c.included||['Editable itinerary','Place stories and transcripts','Local progress'])}</section><section class="rich-card"><h3>Arrange yourself</h3>${list(c.notIncluded||['Transport','Venue tickets','Food and drinks'])}</section></div><section class="rich-card">${section('Ready for less signal?','Save the stories before you head out.')}${downloadRow(templateDownloadState(t.id),t.id)}<p class="fine-print">Downloaded audio and place information. Street directions and new AI requests need separate connectivity.</p></section></div>`,foot:footer(btn('Start tour','start-template',{id:t.id},'','arrow'),textBtn('Save for later','save-template',{id:t.id}))}}
  function proposalView(){const p=ui.proposal?.plan;if(!p)return tripsView();const schedule=timing(p);return {title:'Your suggested day',body:`<div class="page rich-page">${badge('Proposal · review before starting','blue')}${pageHero('A day that fits your curiosity.',`${p.stops.length} stops · ${modeName(p.mode)}`)}${summary(p)}<section class="rich-card">${section('Why this day?')}${list(ui.proposal.explanations?.length?ui.proposal.explanations:['Matched the available place tags to your interests.','Combined visits and estimated transfers within your time window.','You can change the order, durations and stops before starting.'])}${facts([['Start',`${C.formatTime(p.startMinutes)} · ${startName(p.startId)}`],['Visit time',C.formatDuration(schedule.visitMinutes)],['Travel time',C.formatDuration(schedule.travelMinutes)],['Spare time',C.formatDuration(Math.max(0,p.budget-schedule.totalMinutes))]])}</section>${section('Your day, stop by stop','Check the pace before you commit.',textBtn('Customize','edit-proposal',{},'edit'))}${timeline(p,null,true)}<details class="rich-disclosure"><summary>Preview the illustrative route</summary>${map(p)}</details><section class="rich-card">${section('Before you press Start')}<p>Starting saves your personal itinerary. You can pause later, change upcoming visits or keep listening independently.</p>${list(['Check venue hours and entry requirements.','Travel times are planning estimates, not live navigation.','Use external Maps if you need calculated street directions.'])}${textBtn('Ask for an adjustment','adjust-proposal',{},'chat')}</section></div>`,foot:footer(btn('Start this day','start-proposal',{},'','arrow'),textBtn('Save for later','save-proposal'))}}
  function tripCard(t){const s=timing(t.plan),state=h.packageState(t),arrived=t.progress.visited.length;return `<article class="rich-card journey-card"><div class="row between">${badge(({active:'In progress',paused:'Paused',upcoming:'Saved for later',completed:'Completed',ended:'Ended early'})[t.status],t.status==='ended'?'neutral':'blue')}<small>${esc(t.plan.date)}</small></div><h2>${esc(t.plan.title)}</h2><p>${t.plan.stops.length} stops · ${C.formatDuration(s.totalMinutes)} · ${t.plan.mode==='walking'?'Walking':'Car / taxi'}</p>${['active','paused'].includes(t.status)?`<div class="rich-progress"><span style="width:${arrived/t.plan.stops.length*100}%"></span></div><p class="small">Current: ${esc(P[t.plan.stops[t.progress.index].id].name)} · ${arrived} arrivals confirmed</p>`:''}<div class="row between"><span class="download-status">${icon('download')}${esc(state.label)}</span><span class="small muted">${t.plan.stops.filter(x=>P[x.id].story.audio).length} stories</span></div>${btn(t.status==='active'?'Continue my trip':t.status==='paused'?'Resume trip':t.status==='upcoming'?'View saved tour':'View journey','open-trip',{id:t.id},'secondary','arrow')}</article>`}
  function tripsView(){const ts=db().trips,visible=ts.filter(t=>ui.tab==='completed'?['completed','ended'].includes(t.status):['active','paused','upcoming'].includes(t.status)),packages=Object.values(db().packages),favorites=db().favorites.filter(id=>P[id]);return {title:'My Trips',noheader:true,nav:true,body:`<div class="page rich-page">${pageHero('Your journeys, together.','Pick up a story, prepare a day or revisit a memory.')}<div class="profile-stats journey-stats"><div><strong>${ts.filter(t=>['active','paused','upcoming'].includes(t.status)).length}</strong><span>Planned & active</span></div><div><strong>${ts.reduce((n,t)=>n+t.progress.visited.length,0)}</strong><span>Arrivals confirmed</span></div><div><strong>${packages.length}</strong><span>Downloads</span></div></div><div class="segmented" role="tablist" aria-label="Trip status">${['upcoming','completed'].map(v=>`<button role="tab" aria-selected="${ui.tab===v}" data-action="trips-tab" data-value="${v}" class="${ui.tab===v?'active':''}">${v==='upcoming'?'Upcoming & active':'Completed & ended'}</button>`).join('')}</div>${visible.length?visible.map(tripCard).join(''):`<section class="rich-card empty"><span class="circle">${icon('trips')}</span><h2>${ui.tab==='completed'?'The memories come next.':'Your next day starts here.'}</h2><p>${ui.tab==='completed'?'Finished and ended journeys will keep their actual visit history here.':'Choose a prepared route or shape a day around your time.'}</p>${btn('Plan a day','quick-plan',{value:240},'','route')}${textBtn('Browse prepared tours','explore-tours')}</section>`}<section class="rich-card">${section('Your offline shelf',`${packages.length} saved ${packages.length===1?'package':'packages'} · ${((packages.reduce((n,p)=>n+(p.bytes||0),0))/1024/1024).toFixed(1)} MB`)}<p>Keep stories and place information nearby when signal is limited.</p>${btn('Manage downloads','downloads',{},'secondary','download')}</section><section>${section('Places you kept',`${favorites.length} saved ${favorites.length===1?'place':'places'}`)}${favorites.length?`<div class="discover-grid">${favorites.slice(0,4).map(id=>placeCard(P[id])).join('')}</div>`:`<div class="rich-card"><p>Bookmark a place from its detail page. It will be ready to find here.</p>${textBtn('Explore places','all-places',{},'compass')}</div>`}</section><details class="rich-disclosure"><summary>How your journeys are saved</summary><p>Trips, favorites and progress stay in this browser. Signing out of the demo keeps them. There is no cloud sync; browser storage clearing removes local data.</p><p>Arrival and completion are separate: arriving marks a visit; finishing the stop moves you forward.</p></details></div>`}}
  function readyView(){const t=trip();if(!t)return tripsView();return {title:'Your saved tour',body:`<div class="page rich-page">${badge('Personal itinerary · saved here','blue')}${pageHero(t.plan.title,`${t.plan.date} · ${t.plan.stops.length} stops`)}${summary(t.plan)}<section class="rich-card">${section('Your departure brief')}${facts([['Start point',startName(t.plan.startId)],['Planned start',C.formatTime(t.plan.startMinutes)],['Transport',modeName(t.plan.mode)],['End point',t.plan.endMode==='start'?startName(t.plan.startId):P[t.plan.stops.at(-1).id].name]])}</section>${section('A day at your pace','Edit manually or ask for a reviewed suggestion.')}<div class="two">${btn('Edit itinerary','edit-trip',{},'secondary','edit')}${btn('Ask AI','ask-trip',{},'secondary','chat')}</div>${timeline(t.plan,null,true)}<section class="rich-card">${section('Before you go')}${list(['Check current venue access and opening times.','Charge your phone and bring your headphones.','Download stories if connection may be limited.'])}${downloadRow(t)}</section><details class="rich-disclosure"><summary>Route & transport options</summary>${map(t.plan)}${textBtn('Change transport','transport',{},'car')}</details><details class="rich-disclosure"><summary>Manage this saved itinerary</summary><p>Deleting removes this local trip. Other journeys and shared downloaded media are preserved.</p>${textBtn('Delete saved tour…','delete-trip',{},'trash')}</details></div>`,foot:footer(btn('Start tour','start-trip',{},'','arrow'))}}
  function essentialsView(){const city=content().city;return {title:'Trip essentials',body:`<div class="page rich-page">${pageHero('A little preparation goes a long way.','Practical notes for a day in Da Nang.')}<section class="rich-card">${section('Make the day yours')}${list(city.tips||[])}</section><section class="rich-card">${section('Pack for your own pace')}${list(['Headphones for stories and a charged phone.','Water, sun protection and footwear suited to the places you choose.','A rain layer if the forecast suggests you may need it.'])}</section><section class="rich-card">${section('Know what is connected')}${facts([['Weather','City model forecast · Open-Meteo'],['Stories','Bundled English audio and transcripts'],['Navigation','Illustrated route · external Maps for directions'],['AI guide','Local sample answers and planning rules'],['Account','Local demo profile · no cloud sync']])}</section>${btn('Check the city forecast','weather-open',{},'secondary','compass')}${btn('Manage downloaded stories','downloads',{},'secondary','download')}</div>`}}
  function aiOverview(){const t=activeTrip();return `<div class="ai-context-actions">${textBtn('Check the city forecast','weather-open',{},'compass')}${t?textBtn('Adjust my current trip','ask-active-trip',{},'trips'):''}</div><details class="rich-disclosure ai-scope-notes"><summary>What your Guide can help with</summary><p>City mode explains the catalogue and planning options. Place mode answers sample questions using listed sources. Trip mode previews supported changes before you apply them.</p><p>This prototype uses local rules and source-backed samples. Current venue hours, bookings and unrestricted questions are not connected.</p></details>`}

  return {views:{home:homeView,explore:exploreView,tour:tourView,proposal:proposalView,trips:tripsView,ready:readyView,weather:weatherView,essentials:essentialsView,
    place:()=>({title:'Place details',noheader:true,body:detailBody(P[ui.placeId]),foot:footer(btn('Add to trip','add-place-target',{id:ui.placeId},'secondary','plus'))}),
    story:()=>({title:'Story',noheader:true,body:detailBody(P[ui.placeId])}),
    arrival:()=>{const t=trip();if(!t)return tripsView();return {title:'At your stop',noheader:true,body:detailBody(P[t.plan.stops[t.progress.index].id],true),foot:footer(btn(t.progress.index===t.plan.stops.length-1?'Finish this tour':'Finish stop & continue','finish-stop',{},'','arrow'))}}},aiOverview,weatherCard};
}
root.GN_EXPERIENCE={create};
if(typeof module!=='undefined'&&module.exports)module.exports=root.GN_EXPERIENCE;
})(typeof window!=='undefined'?window:globalThis);
